SECTION = SECTION.replace("因此", " потому что").replace("oldым", "старым")


def measure(text):
    rows = re.findall(r"^\|\s*FP-(\d+)\s*\|", text, re.M)
    cls = {}
    for m in re.finditer(r"^\|\s*FP-(\d+)\s*\|(.*?)$", text, re.M):
        mm = re.search(r"`(A1|A2|B1|B2|C)`", m.group(2))
        k = mm.group(1) if mm else "нет"
        cls[k] = cls.get(k, 0) + 1
    q = len(set(re.findall(r"^- Q-(\d+) —", text, re.M)))
    dobyt = sum(1 for ln in text.split("\n") if "Добыть:" in ln)
    n = len(rows)
    return dict(ROWS=n, A1=cls.get("A1", 0), A2=cls.get("A2", 0), B1=cls.get("B1", 0),
                B2=cls.get("B2", 0), C=cls.get("C", 0), QUEUE=q, DOBYT=dobyt,
                SHARE=cls.get("A1", 0) * 100 // max(n, 1), REQ=3)


def occ(path, pat):
    return len(re.findall(re.escape(pat), path.read_text(encoding="utf-8"), re.I))


